<?php if(!$usuarioDetalhe): ?><div class="empty-state"><h2>Usuário não encontrado.</h2></div><?php else: ?><div class="admin-page-title"><div><span class="eyebrow">HISTÓRICO DO CLIENTE</span><h1><?= h($usuarioDetalhe['nome']) ?></h1><p><?= h($usuarioDetalhe['email']) ?> · <?= h($usuarioDetalhe['telefone']) ?></p></div><a class="btn btn-ghost" href="<?= h(url('admin/index.php?secao=usuarios')) ?>">← Usuários</a></div><section class="admin-card"><h2>Compras</h2><?php if(!$detalheCompras): ?><p class="muted">Sem compras.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Data</th><th>Itens</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($detalheCompras as $c): ?><tr><td>#<?= (int)$c['id'] ?></td><td><?= date('d/m/Y',strtotime($c['data_compra'])) ?></td><td><?= (int)$c['itens'] ?></td><td><?= money($c['total']) ?></td><td><?= h(status_label($c['status'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="admin-card"><h2>Aluguéis</h2><?php if(!$detalheAlugueis): ?><p class="muted">Sem aluguéis.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Livro</th><th>Status</th><th>Devolução prevista</th></tr></thead><tbody><?php foreach($detalheAlugueis as $a): ?><tr><td><?= h($a['titulo_snapshot']) ?></td><td><?= h(status_label($a['status'])) ?></td><td><?= $a['data_prevista_devolucao']?date('d/m/Y',strtotime($a['data_prevista_devolucao'])):'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="admin-card"><h2>Multas</h2><?php if(!$detalheMultas): ?><p class="muted">Sem multas.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Livro</th><th>Dias</th><th>Valor</th><th>Status</th></tr></thead><tbody><?php foreach($detalheMultas as $m): ?><tr><td><?= h($m['titulo_snapshot']) ?></td><td><?= (int)$m['dias_atraso'] ?></td><td><?= money($m['valor']) ?></td><td><?= h(status_label($m['status'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
